63|// Strict parse at the trust boundary: exact fields only, so a client
64|// bug cannot silently spend budget on a misread request.
65|export function parseImageRequest(json: unknown): ImageRequest {
66|  if (!isRecord(json)) throw new ImageValidationError();
67|  const { kind } = json;
68|  if (kind === "passage") {
69|    const keys = Object.keys(json).sort().join(",");
70|    if (
71|      keys !== "bookId,kind,n,textVersion" &&
72|      keys !== "bookId,kind,n,style,textVersion" &&
73|      keys !== "bookId,endN,kind,n,textVersion" &&
74|      keys !== "bookId,endN,kind,n,style,textVersion"
75|    ) {
76|      throw new ImageValidationError();
77|    }
78|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
79|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
80|      throw new ImageValidationError();
81|    }
82|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
83|    const endN = json.endN;
84|    if (endN !== undefined && (typeof endN !== "number" || !Number.isInteger(endN))) {
85|      throw new ImageValidationError();
86|    }
87|    const style = parseStyleChoice(json.style);
88|    return {
89|      kind: "passage",
90|      bookId: json.bookId,
91|      textVersion: json.textVersion,
92|      n: json.n,
93|      ...(endN === undefined ? {} : { endN }),
94|      ...(style === undefined ? {} : { style }),
95|    };
96|  }
97|  if (kind === "scene") {
98|    const keys = Object.keys(json).sort().join(",");
99|    if (keys !== "bookId,kind,sceneId,textVersion" && keys !== "bookId,kind,sceneId,style,textVersion") {
100|      throw new ImageValidationError();
101|    }
102|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
103|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
104|      throw new ImageValidationError();
105|    }
106|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
107|    const style = parseStyleChoice(json.style);
108|    return {
109|      kind: "scene",
110|      bookId: json.bookId,
111|      textVersion: json.textVersion,
112|      sceneId: json.sceneId,
113|      ...(style === undefined ? {} : { style }),
