148|// Checks the parsed request against the frozen book text.
149|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
150|  if (req.bookId !== book.id) throw new ImageValidationError();
151|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
152|  if (req.kind === "passage") {
153|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
154|    if (req.endN !== undefined && (req.endN < req.n || !book.paragraphNs.has(req.endN))) {
155|      throw new ImageValidationError();
156|    }
157|    return;
158|  }
159|  if (req.kind === "scene") {
160|    if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
161|    return;
162|  }
163|  if (!book.chapters.has(req.ch)) throw new ImageValidationError();
164|}
