166|// One paragraph maps to one image; one scene maps to one image; one
167|// chapter maps to one comic page. A styled image keeps the same base with
168|// a style segment before the file name, so an omitted style keys
169|// byte-identically to today. A multi-paragraph passage keeps pN when endN
170|// is absent or equals n, so old images keep hitting; a wider range gets
171|// pN-M.
172|export function imageKey(req: ImageRequest): string {
173|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
174|  const file =
175|    req.kind === "passage"
176|      ? req.endN === undefined || req.endN === req.n
177|        ? `p${req.n}.webp`
178|        : `p${req.n}-${req.endN}.webp`
179|      : req.kind === "scene"
180|        ? `scene-${req.sceneId}.webp`
181|        : `chapter-${req.ch}-${CHAPTER_PROMPT_VERSION}.webp`;
182|  return req.style === undefined ? `${base}/${file}` : `${base}/${styleSegment(req.style)}/${file}`;
183|}
