285|// In-memory KV for tests. Expiries are checked against Date.now.
286|export function createMemoryKV(): KV & { clear(): void } {
287|  const values = new Map<string, string>();
288|  const expiresAt = new Map<string, number>();
289|  function live(key: string): boolean {
290|    const until = expiresAt.get(key);
291|    if (until !== undefined && Date.now() >= until) {
292|      values.delete(key);
293|      expiresAt.delete(key);
294|      return false;
295|    }
296|    return true;
297|  }
298|  function num(key: string): number {
299|    return Number(values.get(key) ?? "0");
300|  }
301|  return {
302|    async get(key: string): Promise<string | null> {
303|      if (!live(key)) return null;
304|      return values.get(key) ?? null;
305|    },
306|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
307|      if (live(key) && values.has(key)) return false;
308|      values.set(key, value);
309|      expiresAt.set(key, Date.now() + exSec * 1000);
310|      return true;
311|    },
312|    async set(key: string, value: string): Promise<void> {
313|      values.set(key, value);
314|      expiresAt.delete(key);
315|    },
316|    async incr(key: string): Promise<number> {
317|      const next = num(key) + 1;
318|      values.set(key, String(next));
319|      return next;
320|    },
321|    async incrBy(key: string, by: number): Promise<number> {
322|      const next = num(key) + by;
323|      values.set(key, String(next));
324|      return next;
325|    },
326|    async decr(key: string): Promise<number> {
327|      const next = num(key) - 1;
328|      values.set(key, String(next));
329|      return next;
330|    },
331|    async decrBy(key: string, by: number): Promise<number> {
332|      const next = num(key) - by;
333|      values.set(key, String(next));
334|      return next;
335|    },
336|    async expire(key: string, sec: number): Promise<void> {
337|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
338|    },
339|    async releaseIfToken(key: string, token: string): Promise<boolean> {
340|      if (!live(key)) return false;
341|      if (values.get(key) !== token) return false;
342|      values.delete(key);
343|      expiresAt.delete(key);
344|      return true;
345|    },
346|    clear(): void {
347|      values.clear();
348|      expiresAt.clear();
349|    },
350|  };
