1|// Pure range logic for passage-picture reuse: an overlapping selection
2|// reuses a cached picture, a much larger or smaller one gets its own.
3|import { imageKey } from "./images";
4|import type { PassageRequest } from "./types";
5|
6|export interface ParaRange {
7|  start: number;
8|  end: number;
9|}
10|
11|// Reuse a cached picture when |A∩B|/|A∪B| over paragraphs is at least
12|// this; a much larger or smaller selection falls below and gets its own
13|// picture.
14|export const REUSE_JACCARD = 0.5;
15|
16|// Bounds the per-scene lookup.
17|export const MAX_RANGES_PER_SCENE = 24;
18|
19|export function jaccard(a: ParaRange, b: ParaRange): number {
20|  const inter = Math.max(0, Math.min(a.end, b.end) - Math.max(a.start, b.start) + 1);
21|  const union = a.end - a.start + 1 + (b.end - b.start + 1) - inter;
22|  return union <= 0 ? 0 : inter / union;
23|}
24|
25|export function pickReusable(cached: readonly ParaRange[], want: ParaRange): ParaRange | null {
26|  let best: ParaRange | null = null;
27|  let bestScore = 0;
28|  for (const c of cached) {
29|    const score = jaccard(c, want);
30|    if (score >= REUSE_JACCARD && score > bestScore) {
31|      best = c;
32|      bestScore = score;
33|    }
34|  }
35|  return best;
36|}
37|
38|// Parses the stored range list; drops garbage entries, never throws.
39|export function parseRanges(raw: string | null): ParaRange[] {
40|  if (!raw) return [];
41|  let parsed: unknown;
42|  try {
43|    parsed = JSON.parse(raw);
44|  } catch {
45|    return [];
46|  }
47|  if (!Array.isArray(parsed)) return [];
48|  const out: ParaRange[] = [];
49|  for (const item of parsed) {
50|    if (typeof item !== "object" || item === null || Array.isArray(item)) continue;
51|    const { start, end } = item as Record<string, unknown>;
52|    if (typeof start !== "number" || !Number.isInteger(start)) continue;
53|    if (typeof end !== "number" || !Number.isInteger(end)) continue;
54|    if (end < start) continue;
55|    out.push({ start, end });
56|  }
57|  return out;
58|}
59|
60|export function addRange(list: readonly ParaRange[], r: ParaRange): ParaRange[] {
61|  if (list.some((e) => e.start === r.start && e.end === r.end)) return [...list];
62|  return [...list, r].slice(-MAX_RANGES_PER_SCENE);
63|}
64|
65|// The scene's range list lives next to its images; built from imageKey's
66|// directory so the two never drift.
67|export function rangeListKeyFor(req: PassageRequest, sceneId: string): string {
68|  const key = imageKey(req);
69|  return `img:ranges:${key.slice(0, key.lastIndexOf("/"))}/${sceneId}`;
70|}

