34|export function usePictureLoaded(url: string) {
35|  // True once the ready image has actually loaded. The url sits next to
36|  // the flag so a cached ready-to-ready swap resets in the same render,
37|  // never flashing the new image as revealed.
38|  const [state, setState] = useState({ url, loaded: false });
39|  if (state.url !== url) setState({ url, loaded: false });
40|  // Derived, so even the resetting render reports the new url as waiting.
41|  const loaded = state.url === url && state.loaded;
42|  const imgRef = useCallback(
43|    (el: HTMLImageElement | null) => {
44|      if (el && el.complete && el.naturalWidth > 0)
45|        setState((s) => (s.url === url ? { ...s, loaded: true } : s));
46|    },
47|    [url],
48|  );
49|  // Late events from a previous image must not mark the new url loaded.
50|  const markLoaded = useCallback(
51|    () => setState((s) => (s.url === url ? { ...s, loaded: true } : s)),
52|    [url],
53|  );
54|  return { loaded, imgRef, markLoaded };
