25|  ch: number;
26|  chapterTitle: string;
27|  panels: ChapterPanel[];
28|  bookId: string;
29|  textVersion: string;
30|  pref: ImageStylePref;
31|  reached: boolean;
32|  onClose: () => void;
33|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
34|}) {
