36|  const skin = usePictureSkin();
37|  const { page, retry } = useChapterPage({ bookId, textVersion, ch, pref, reached });
38|  const closeRef = useRef<HTMLButtonElement | null>(null);
39|  const boxRef = useRef<HTMLDivElement | null>(null);
40|
41|  useEffect(() => {
42|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
43|    closeRef.current?.focus();
44|    const onKey = (event: KeyboardEvent) => {
45|      if (event.key === "Escape") {
46|        // The shared lightbox sits above the modal and closes itself.
47|        if (document.querySelector(".lightbox")) return;
48|        event.stopPropagation();
49|        onClose();
50|        return;
51|      }
52|      if (event.key !== "Tab" || !boxRef.current) return;
53|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
54|        (el) => !el.hasAttribute("disabled"),
