56|      if (items.length === 0) return;
57|      const first = items[0] as HTMLElement;
58|      const last = items[items.length - 1] as HTMLElement;
59|      if (event.shiftKey && document.activeElement === first) {
60|        event.preventDefault();
61|        last.focus();
62|      } else if (!event.shiftKey && document.activeElement === last) {
63|        event.preventDefault();
