1|// One comic page per chapter, requested in the reader's style. Session
2|// cache per chapter and style, so reopening never refetches.
3|"use client";
4|
5|import { useCallback, useEffect, useRef, useState } from "react";
6|import { MSG_FAILED } from "@/core/images";
7|import { requestStyleFields } from "../image-style";
8|import type { ImageStylePref } from "../image-style";
9|import { poll } from "./use-pictures";
10|
11|export type ChapterPage =
12|  | { phase: "loading" }
13|  | { phase: "ready"; url: string; caption: string }
14|  | { phase: "error"; message: string };
15|
16|const chapterCache = new Map<string, { url: string; caption: string }>();
17|
18|function cacheKey(ch: number, pref: ImageStylePref): string {
19|  return `${ch}::${JSON.stringify(requestStyleFields(pref))}`;
20|}
21|
22|export function useChapterPage({
23|  bookId,
24|  textVersion,
25|  ch,
26|  pref,
27|  reached,
28|}: {
29|  bookId: string;
30|  textVersion: string;
31|  ch: number;
32|  pref: ImageStylePref;
33|  reached: boolean;
34|}): { page: ChapterPage; retry: () => void } {
35|  // The style pref arrives as a fresh object each render and is read
36|  // through a ref, like use-pictures; the key string tracks its value.
37|  const prefRef = useRef(pref);
38|  prefRef.current = pref;
39|  const key = cacheKey(ch, pref);
40|  const [page, setPage] = useState<ChapterPage>(() => {
41|    const hit = chapterCache.get(key);
42|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "loading" };
43|  });
44|  const [attempt, setAttempt] = useState(0);
45|
46|  useEffect(() => {
47|    if (!reached) return;
48|    const hit = chapterCache.get(key);
49|    if (hit) {
50|      setPage({ phase: "ready", url: hit.url, caption: hit.caption });
51|      return;
52|    }
53|    setPage({ phase: "loading" });
54|    let cancelled = false;
55|    void poll({ kind: "chapter", bookId, textVersion, ch, ...requestStyleFields(prefRef.current) })
56|      .then(({ url, caption }) => {
57|        chapterCache.set(key, { url, caption });
58|        if (!cancelled) setPage({ phase: "ready", url, caption });
59|      })
60|      .catch((err: unknown) => {
61|        if (!cancelled) {
62|          setPage({ phase: "error", message: err instanceof Error ? err.message : MSG_FAILED });
63|        }
64|      });
65|    return () => {
66|      cancelled = true;
67|    };
68|  }, [bookId, textVersion, ch, key, reached, attempt]);
69|
70|  const retry = useCallback(() => setAttempt((n) => n + 1), []);
71|  return { page, retry };
72|}

