1|// Chapter panels: one comic page per chapter, captions below it in
2|// reading order. The page generates on demand in the reader's style;
3|// chapters past the reader's reach stay gated.
4|"use client";
5|
6|import { useEffect, useRef } from "react";
7|import type { ImageStylePref } from "../image-style";
8|import type { ChapterPanel } from "./panels";
9|import { PICTURE_COPY } from "./picture-copy";
10|import { PictureDraw, PictureWait } from "./picture-draw";
11|import { usePictureSkin } from "./picture-skin";
12|import { useChapterPage } from "./use-chapter-page";
13|
14|export function PanelsModal({
15|  ch,
16|  chapterTitle,
17|  panels,
18|  bookId,
19|  textVersion,
20|  pref,
21|  reached,
22|  onClose,
23|  onOpenArt,
24|}: {
25|  ch: number;
26|  chapterTitle: string;
27|  panels: ChapterPanel[];
28|  bookId: string;
29|  textVersion: string;
30|  pref: ImageStylePref;
31|  reached: boolean;
32|  onClose: () => void;
33|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
34|}) {
35|  const chapterLabel = `Chapter ${ch}, ${chapterTitle}`;
36|  const skin = usePictureSkin();
37|  const { page, retry } = useChapterPage({ bookId, textVersion, ch, pref, reached });
38|  const closeRef = useRef<HTMLButtonElement | null>(null);
39|  const boxRef = useRef<HTMLDivElement | null>(null);
40|
41|  useEffect(() => {
42|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
43|    closeRef.current?.focus();
44|    const onKey = (event: KeyboardEvent) => {
45|      if (event.key === "Escape") {
46|        // The shared lightbox sits above the modal and closes itself.
47|        if (document.querySelector(".lightbox")) return;
48|        event.stopPropagation();
49|        onClose();
50|        return;
51|      }
52|      if (event.key !== "Tab" || !boxRef.current) return;
53|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
54|        (el) => !el.hasAttribute("disabled"),
55|      );
56|      if (items.length === 0) return;
57|      const first = items[0] as HTMLElement;
58|      const last = items[items.length - 1] as HTMLElement;
59|      if (event.shiftKey && document.activeElement === first) {
60|        event.preventDefault();
61|        last.focus();
62|      } else if (!event.shiftKey && document.activeElement === last) {
63|        event.preventDefault();
64|        first.focus();
65|      }
66|    };
67|    document.addEventListener("keydown", onKey, true);
68|    return () => {
69|      document.removeEventListener("keydown", onKey, true);
70|      opener?.focus?.({ preventScroll: true });
71|    };
72|  }, [onClose]);
73|
74|  return (
75|    <div className="panels-modal" role="dialog" aria-modal="true" aria-label={chapterLabel}>
76|      <div ref={boxRef} className="panels-box">
77|        <button ref={closeRef} type="button" className="panels-x" onClick={onClose} aria-label="Close">
78|          ×
79|        </button>
80|        <p className="panels-head">
81|          Chapter {ch} · {chapterTitle}
82|        </p>
83|        {reached ? (
84|          <>
85|            {page.phase === "ready" ? (
86|              <button
87|                type="button"
88|                className="panels-frame"
89|                onClick={(e) => onOpenArt(page.url, chapterLabel, e.currentTarget)}
90|                aria-label={`Open art: ${chapterLabel}`}
91|              >
92|                <img src={page.url} alt="" />
93|              </button>
94|            ) : page.phase === "loading" ? (
95|              <div className="panels-frame">
96|                <PictureDraw skin={skin} />
97|              </div>
98|            ) : (
99|              <div className="panels-frame panels-miss" role="alert">
100|                <p>{page.message}</p>
101|                <button type="button" className="retry-text" onClick={retry}>
102|                  {PICTURE_COPY.retry}
103|                </button>
104|              </div>
105|            )}
106|            {page.phase === "loading" ? <PictureWait skin={skin} /> : null}
107|            <ol className="panels-caps">
108|              {panels.map((p) => (
109|                <li key={p.key}>{p.caption}</li>
110|              ))}
111|            </ol>
112|          </>
113|        ) : (
114|          <p className="panels-gate">Read up to this chapter first.</p>
115|        )}
116|      </div>
117|    </div>
118|  );
119|}

