68|  // the base passes run out, further light layers keep appending, so
69|  // the tool keeps working but nothing already drawn is ever wiped.
70|  const [strokes, setStrokes] = useState<FlatStroke[]>(() =>
71|    [0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)),
72|  );
73|  const nextLayer = useRef(4);
74|  useEffect(() => {
75|    nextLayer.current = 4;
76|    setStrokes([0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)));
77|  }, [skin]);
78|  const strokesRef = useRef(strokes);
79|  strokesRef.current = strokes;
80|  const stillAll = useMemo(() => stillStrokes(skin), [skin]);
81|  const still = stillMode ? stillAll : null;
