84|  useEffect(() => {
85|    if (stillMode) return;
86|    const paths = pathRefs.current;
87|    const tool = toolRef.current;
88|    let dead = false;
89|    let frame = 0;
90|    const pos = { x: 340, y: 304 };
91|    const place = (x: number, y: number) => {
92|      pos.x = x;
93|      pos.y = y;
94|      tool?.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
95|    };
96|    place(pos.x, pos.y);
