102|        return { x: pt.x, y: pt.y };
103|      } catch {
104|        return null;
105|      }
106|    };
107|
108|    // Draw every stroke once, in order, and keep it: outline first,
109|    // then shading layers on top. Past the base passes, further light
110|    // layers append so the tool keeps working without ever wiping.
111|    let i = 0;
112|    const stepStroke = () => {
113|      if (dead) return;
114|      if (i >= strokesRef.current.length) {
115|        const layer = strokesForSkin(skin, nextLayer.current);
