145|        frame = requestAnimationFrame(tick);
146|        return;
147|      }
148|      const k = Math.min(1, (now - t0 - TRAVEL) / dur);
149|      if (spec.fill) {
150|        el.setAttribute("opacity", String(spec.opacity * k));
151|        if (k < 1) place(pos.x + Math.sin(k * 9) * 3, pos.y + Math.cos(k * 7) * 2);
152|      } else {
153|        el.setAttribute("opacity", String(spec.opacity));
154|        el.style.strokeDashoffset = String(1 - k);
155|        const pt = pointAt(el, k);
156|        if (pt) place(pt.x, pt.y);
157|      }
158|      if (k < 1) frame = requestAnimationFrame(tick);
159|      else stepStroke();
160|    };
161|    frame = requestAnimationFrame(tick);
162|  };
163|  stepStroke();
164|  return () => {
165|    dead = true;
166|    cancelAnimationFrame(frame);
167|  };
168|}, [stillMode, skin]);
169|
170|  return (
