1|// The whole book as one continuous scroll: every chapter with its panels
2|// strip inline, every scene a section. The scene most in view drives the
3|// picture card, the vault, the pager, and the music session. Native
4|// scrolling only: no wheel hijacking, no sub-pages, no page-turn keys.
5|"use client";
6|
7|import { Fragment, useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
8|import type { ReaderModel } from "@/core/reader";
