92|    setCurrentSceneId(initialSceneId);
93|    scrollToSceneId(col, initialSceneId, false);
94|    return attachFollowPause(col);
95|  }, [initialSceneId]);
96|
97|  // The scene under the reading line (40% down the column) is current.
98|  // A thin rootMargin band, not ratios: a long scene filling the screen
99|  // must beat a short one fully in view, and the band fires exactly when
100|  // a section crosses the line. Ties keep document order. One observer,
101|  // no scroll listeners, no layout reads on scroll.
102|  useEffect(() => {
103|    const col = readColRef.current;
104|    if (!col) return;
105|    const seen = new Map<string, { id: string; ratio: number }>();
106|    const io = new IntersectionObserver(
107|      (entries) => {
108|        for (const entry of entries) {
109|          const id = (entry.target as HTMLElement).dataset.sceneId;
110|          if (!id) continue;
111|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
112|          else seen.delete(id);
113|        }
114|        const next = pickCurrentScene(order, seen);
115|        if (next) commitScene(next);
116|      },
117|      { root: col, rootMargin: "-40% 0px -59% 0px", threshold: 0 },
118|    );
119|    for (const section of col.querySelectorAll("[data-scene-id]")) io.observe(section);
