187|      />
188|      <Divider />
189|      <div className="read-col" ref={readColRef} tabIndex={-1} aria-label="Reading column" onMouseUp={onReadMouseUp}>
190|        <ReadAlong columnRef={readColRef} />
191|        {model.chapters.map((chapter) => {
