1|// The whole book as one continuous scroll: every chapter with its panels
2|// strip inline, every scene a section. The scene most in view drives the
3|// picture card, the vault, the pager, and the music session. Native
4|// scrolling only: no wheel hijacking, no sub-pages, no page-turn keys.
5|"use client";
6|
7|import { Fragment, useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
8|import type { ReaderModel } from "@/core/reader";
9|import { effectiveImageStylePref, loadImageStylePref, saveImageStylePref } from "../image-style";
10|import type { ImageStylePref } from "../image-style";
11|import { useSkin } from "../use-skin";
12|import { BandPager, Divider } from "../folio/chrome";
13|import { figuresAfter, groupFiguresByEndN } from "../folio/figure-placement";
14|import { ImagePane } from "../folio/image-pane";
15|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
16|import { Lightbox } from "../folio/lightbox";
17|import { usePictures } from "../folio/use-pictures";
18|import type { InlineFigure } from "../folio/use-pictures";
19|import { PictureVault } from "../folio/vault";
20|import { coverTitleLong } from "../folio/panels";
21|import type { ChapterPanel } from "../folio/panels";
22|import { PanelsModal } from "../folio/panels-modal";
23|import { GOTO_SCENE_EVENT, setCurrentSceneId } from "./current-scene";
24|import { attachFollowPause, noteUserScroll, pickCurrentScene, scrollToSceneId } from "./scroll-helpers";
25|import { ReadAlong } from "../narration/read-along";
26|
27|function pulse(el: HTMLElement | null) {
28|  if (!el) return;
29|  el.classList.remove("pulse");
30|  void el.offsetWidth;
31|  el.classList.add("pulse");
32|  window.setTimeout(() => el.classList.remove("pulse"), 650);
33|}
34|
35|export function BookView({
36|  model,
37|  initialSceneId,
38|  panelsByChapter,
39|}: {
40|  model: ReaderModel;
41|  initialSceneId: string;
42|  panelsByChapter: { ch: number; panels: ChapterPanel[] }[];
43|}) {
44|  const [storedPref, setStoredPref] = useState<ImageStylePref | null>(null);
45|  // Server render uses the default so hydration matches; the live skin
46|  // applies on mount via useSyncExternalStore.
47|  const skin = useSkin();
48|  const pref = effectiveImageStylePref(storedPref, skin);
49|  const [currentId, setCurrentId] = useState(initialSceneId);
50|  const [panelsCh, setPanelsCh] = useState<number | null>(null);
51|  const readColRef = useRef<HTMLDivElement | null>(null);
52|  const figEls = useRef(new Map<string, HTMLElement>());
53|  const pic = usePictures({ bookId: model.bookId, textVersion: model.textVersion, sceneId: currentId, pref });
54|  const order = useMemo(() => model.chapters.flatMap((c) => c.scenes.map((s) => s.id)), [model]);
55|  const sceneOf = useMemo(() => {
56|    const map = new Map<string, { ch: number; k: number; n: number; chapterTitle: string }>();
57|    for (const chapter of model.chapters) {
58|      chapter.scenes.forEach((s, i) => {
59|        map.set(s.id, { ch: chapter.ch, k: i + 1, n: chapter.scenes.length, chapterTitle: chapter.title });
60|      });
61|    }
62|    return map;
63|  }, [model]);
64|  const panelsOf = useMemo(() => new Map(panelsByChapter.map((e) => [e.ch, e.panels])), [panelsByChapter]);
65|  const titles = useMemo(() => new Map(model.chapters.map((c) => [c.ch, c.title])), [model]);
66|  const info = sceneOf.get(currentId);
67|  // Spoiler reach: the highest chapter in view this visit. A chapter's
68|  // page and captions load only once the reader has reached it.
69|  const [maxReached, setMaxReached] = useState(() => sceneOf.get(initialSceneId)?.ch ?? 1);
70|  const infoCh = info?.ch;
71|  useEffect(() => {
72|    if (infoCh !== undefined) setMaxReached((prev) => Math.max(prev, infoCh));
73|  }, [infoCh]);
74|  const bookIndex = order.indexOf(currentId);
75|  const lastChapter = model.chapters[model.chapters.length - 1]?.ch ?? 0;
76|
77|  // One commit path for every scene change: state, the live store the
78|  // music container reads, and the deep-link URL. No router pushes, so
79|  // scrolling never remounts.
80|  const commitScene = useCallback((id: string) => {
81|    setCurrentId((prev) => (prev === id ? prev : id));
82|    setCurrentSceneId(id);
83|    window.history.replaceState(null, "", `/leer/${id}`);
84|  }, []);
85|
86|  // Land on the deep-linked scene with no animation, focus the column so
87|  // native keys scroll it, and pause narration follow on user input.
88|  useEffect(() => {
89|    const col = readColRef.current;
90|    if (!col) return;
91|    col.focus({ preventScroll: true });
92|    setCurrentSceneId(initialSceneId);
93|    scrollToSceneId(col, initialSceneId, false);
94|    return attachFollowPause(col);
95|  }, [initialSceneId]);
96|
97|  // The scene under the reading line (40% down the column) is current.
98|  // A thin rootMargin band, not ratios: a long scene filling the screen
99|  // must beat a short one fully in view, and the band fires exactly when
100|  // a section crosses the line. Ties keep document order. One observer,
101|  // no scroll listeners, no layout reads on scroll.
102|  useEffect(() => {
103|    const col = readColRef.current;
104|    if (!col) return;
105|    const seen = new Map<string, { id: string; ratio: number }>();
106|    const io = new IntersectionObserver(
107|      (entries) => {
108|        for (const entry of entries) {
109|          const id = (entry.target as HTMLElement).dataset.sceneId;
110|          if (!id) continue;
111|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
112|          else seen.delete(id);
113|        }
114|        const next = pickCurrentScene(order, seen);
115|        if (next) commitScene(next);
116|      },
117|      { root: col, rootMargin: "-40% 0px -59% 0px", threshold: 0 },
118|    );
119|    for (const section of col.querySelectorAll("[data-scene-id]")) io.observe(section);
120|    return () => io.disconnect();
121|  }, [order, commitScene]);
122|
123|  // Chapter jumps from outside the column arrive here.
124|  useEffect(() => {
125|    const onGoto = (event: Event) => gotoScene((event as CustomEvent<string>).detail);
126|    window.addEventListener(GOTO_SCENE_EVENT, onGoto);
127|    return () => window.removeEventListener(GOTO_SCENE_EVENT, onGoto);
128|  }, [gotoScene]);
129|
130|  useEffect(() => {
131|    setStoredPref(loadImageStylePref());
132|  }, []);
133|
134|  function changePref(next: ImageStylePref) {
135|    setStoredPref(next);
136|    saveImageStylePref(next);
137|  }
138|
139|  const closePanels = useCallback(() => setPanelsCh(null), []);
140|
141|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
142|
143|  function gotoFigure(fig: InlineFigure) {
144|    const el = figEls.current.get(fig.id) ?? null;
145|    const col = readColRef.current;
146|    if (col) noteUserScroll(col);
147|    el?.scrollIntoView({ block: "nearest" });
148|    pulse(el);
149|  }
150|
151|  function gotoScenePicture() {
152|    const img = document.querySelector(".img-pane .pane-img");
153|    pulse(img instanceof HTMLElement ? img : null);
154|  }
155|
156|  function gotoScene(id: unknown) {
157|    if (typeof id !== "string") return;
158|    pic.hidePopover();
159|    const col = readColRef.current;
160|    if (col) scrollToSceneId(col, id, true);
161|  }
162|
163|  // A selection that starts in another scene moves the current scene
164|  // there; the popover follows without a second tap. Chapter headings and
165|  // the panels strip sit outside scene sections, so they never offer it.
166|  function onReadMouseUp() {
167|    const sel = window.getSelection();
168|    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
169|    const node = sel.anchorNode;
170|    const el = node instanceof Element ? node : node?.parentElement ?? null;
171|    const section = el?.closest?.("[data-scene-id]") ?? null;
172|    const id = section instanceof HTMLElement ? section.dataset.sceneId : null;
173|    if (!id || id === currentId) return;
174|    commitScene(id);
175|    requestAnimationFrame(() => pic.rescan());
176|  }
177|
178|  return (
179|    <>
180|      <ImagePane
181|        card={pic.card}
182|        onPicture={() => pic.illustrateScene()}
183|        onRetry={() => pic.illustrateScene()}
184|        onClear={pic.clearScene}
185|        onOpen={pic.lightbox.open}
186|        onPictureChapter={info ? () => setPanelsCh(info.ch) : null}
187|      />
188|      <Divider />
189|      <div className="read-col" ref={readColRef} tabIndex={-1} aria-label="Reading column" onMouseUp={onReadMouseUp}>
190|        <ReadAlong columnRef={readColRef} />
191|        {model.chapters.map((chapter) => {
192|          const coverLong = coverTitleLong(chapter.title);
193|          return (
194|            <div className="chapter-block" key={chapter.ch}>
195|              <div className="kicker">Chapter</div>
196|              <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${chapter.ch}`}>
197|                {chapter.ch}
198|              </p>
199|              <h1 className="chapter-title cover-title" data-long={coverLong}>
200|                {chapter.title}
201|              </h1>
202|              <hr className="cover-rule" />
203|              {chapter.scenes.map((s, si) => (
204|                <section
205|                  key={s.id}
206|                  className="book-section"
207|                  data-scene-id={s.id}
208|                  aria-label={s.title}
209|                  // Strings for the skin's `content:`; counters can't cross content-visibility.
210|                  style={
211|                    {
212|                      "--scene-n": `"${si + 1}"`,
213|                      "--scene-of": `" of ${chapter.scenes.length}"`,
214|                    } as CSSProperties
215|                  }
216|                >
217|                  <div
218|                    className={si === 0 ? "body-text dropcap" : "body-text"}
219|                    ref={s.id === currentId ? pic.viewRef : undefined}
220|                  >
221|                    {s.paragraphs.map((p, i, arr) => (
222|                      <Fragment key={p.id}>
223|                        <p id={p.id} data-n={p.n}>
224|                          {p.text}
225|                        </p>
226|                        {figuresAfter(arr, i, figsByN).map((fig) => (
227|                          <InlineFigureView
228|                            key={fig.id}
229|                            figure={fig}
230|                            onRemove={() => pic.removeFigure(fig.id)}
231|                            onRetry={() => pic.retryFigure(fig.id)}
232|                            onOpen={pic.lightbox.open}
233|                            refCb={(el) => {
234|                              if (el) figEls.current.set(fig.id, el);
235|                              else figEls.current.delete(fig.id);
236|                            }}
237|                          />
238|                        ))}
239|                      </Fragment>
240|                    ))}
241|                    {s.id === currentId && pic.popover !== null ? (
242|                      <SelectionPopover pos={pic.popover} popRef={pic.popRef} onPick={() => pic.illustratePassage()} />
243|                    ) : null}
244|                  </div>
245|                </section>
246|              ))}
247|              {chapter.ch === lastChapter ? (
248|                <p className="the-end">The end.</p>
249|              ) : (
250|                <div className="chapter-relive">
251|                  <button
252|                    type="button"
253|                    className="panels-link"
254|                    onClick={() => setPanelsCh(chapter.ch)}
255|                  >
256|                    Relive this chapter in panels
257|                  </button>
258|                </div>
259|              )}
260|            </div>
261|          );
262|        })}
263|      </div>
264|      <PictureVault
265|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
266|        figures={pic.figures}
267|        onGotoScene={gotoScenePicture}
268|        onGotoFigure={gotoFigure}
269|        onOpen={pic.lightbox.open}
270|        pref={pref}
271|        onPrefChange={changePref}
272|      />
273|      <BandPager
274|        k={info?.k ?? 1}
275|        n={info?.n ?? 1}
276|        bookIndex={Math.max(0, bookIndex)}
277|        bookTotal={order.length}
278|        onPrev={() => gotoScene(bookIndex > 0 ? order[bookIndex - 1] : undefined)}
279|        onNext={() => gotoScene(bookIndex < order.length - 1 ? order[bookIndex + 1] : undefined)}
280|        atStart={bookIndex <= 0}
281|        atBookEnd={bookIndex >= order.length - 1}
282|      />
283|      <Lightbox item={pic.lightbox.item} onClose={pic.lightbox.close} />
284|      {panelsCh !== null ? (
285|        <PanelsModal
286|          ch={panelsCh}
287|          chapterTitle={titles.get(panelsCh) ?? ""}
288|          panels={panelsOf.get(panelsCh) ?? []}
289|          bookId={model.bookId}
290|          textVersion={model.textVersion}
291|          pref={pref}
292|          reached={panelsCh <= maxReached}
293|          onClose={closePanels}
294|          onOpenArt={pic.lightbox.open}
295|        />
296|      ) : null}
297|    </>
298|  );
299|}

