38|    save: async (path, bytes) => {
39|      if (files.has(path)) throw new Error("overwrite");
40|      files.set(path, bytes);
41|      return `https://blob.example/${path}`;
42|    },
43|  };
44|  const generate: ImageGenerator = {
45|    generate: async () => new Uint8Array([1, 2, 3]),
46|  };
