63|    let prompt = "";
64|    const d = deps({
65|      generate: {
66|        generate: async (p: string) => {
67|          prompt = p;
68|          return new Uint8Array([9]);
69|        },
70|      },
71|    });
72|    const res = await orchestrate(chapter(1), d);
73|    expect(res).toMatchObject({ status: "ready", cached: false, caption: "The Cyclone" });
74|    expect(prompt).toContain('Chapter "The Cyclone"');
75|    expect(prompt).toContain("Panel 1:");
76|    expect(prompt).toContain("Panel 2:");
77|    expect(prompt).toContain("speech balloons");
78|  });
79|
80|  it("serves a cached hit without quota, spend, or generate", async () => {
81|    let calls = 0;
82|    const d = deps({
83|      generate: {
84|        generate: async () => {
85|          calls++;
86|          return new Uint8Array([9]);
87|        },
88|      },
89|    });
90|    expect((await orchestrate(chapter(1), d)).status).toBe("ready");
